/* ===== CATEGORY + SEARCH FILTERING ===== */
let activeCategory = 'all';

function setActivePill(filterVal){
  document.querySelectorAll('.cat-pill').forEach(p=>{
    const isOn = p.getAttribute('data-filter') === filterVal;
    p.classList.toggle('on', isOn);
    p.setAttribute('aria-pressed', String(isOn));
  });
}

function applyFilters(){
  const query = (document.getElementById('heroSearchInput')?.value || '').trim().toLowerCase();
  const groups = [
    { selector: '#listings .grid > .card[data-job-id]', emptyId: 'listingsEmptyMsg' },
    { selector: '#private .grid > .card[data-job-id]', emptyId: 'privateEmptyMsg' }
  ];
  groups.forEach(group=>{
    const cards = document.querySelectorAll(group.selector);
    let anyVisible = false;
    cards.forEach(card=>{
      const cat = card.getAttribute('data-category');
      const matchesCategory = (activeCategory === 'all') || (cat === activeCategory);
      const matchesQuery = !query || card.textContent.toLowerCase().includes(query);
      const visible = matchesCategory && matchesQuery;
      card.style.display = visible ? '' : 'none';
      if(visible) anyVisible = true;
    });
    const emptyEl = document.getElementById(group.emptyId);
    if(emptyEl) emptyEl.style.display = anyVisible ? 'none' : 'block';
  });
}

document.querySelectorAll('.cat-pill').forEach(pill=>{
  pill.addEventListener('click', ()=>{
    const filterVal = pill.getAttribute('data-filter') || 'all';
    setActivePill(filterVal);
    activeCategory = filterVal;
    applyFilters();
  });
  pill.addEventListener('keydown', (e)=>{
    if(e.key === 'Enter' || e.key === ' '){
      e.preventDefault();
      pill.click();
    }
  });
});

document.querySelectorAll('nav.links a[data-filter]').forEach(a=>{
  a.addEventListener('click', ()=>{
    const filterVal = a.getAttribute('data-filter');
    setActivePill(filterVal);
    activeCategory = filterVal;
    applyFilters();
  });
});

