/* ===== LATEST UPDATES LIST ===== */
function renderUpdatesList(){
  const listEl = document.getElementById('updatesList');
  if(!listEl) return;
  const cards = Array.from(document.querySelectorAll('.card[data-posted]'));
  const items = cards.map(card=>{
    const jobId = card.getAttribute('data-job-id');
    const posted = card.getAttribute('data-posted');
    const titleDict = dict[jobId + 'title'];
    return {
      jobId,
      posted,
      title: titleDict ? titleDict[currentLang] : ''
    };
  }).filter(it=> it.title);

  items.sort((a,b)=> new Date(b.posted) - new Date(a.posted));
  const top = items.slice(0, 6);

  if(top.length === 0){
    listEl.innerHTML = '<li class="updates-empty">' + dict.updatesEmpty[currentLang] + '</li>';
    return;
  }

  const dateFmt = (iso)=>{
    const d = new Date(iso + 'T00:00:00');
    const dd = String(d.getDate()).padStart(2,'0');
    const mm = String(d.getMonth()+1).padStart(2,'0');
    return dd + '/' + mm;
  };

  listEl.innerHTML = top.map(it=>
    '<li><button type="button" data-goto-job="' + it.jobId + '">'
    + '<span class="ud-title">' + escapeHtml(it.title) + '</span>'
    + '<span class="ud-date">' + dateFmt(it.posted) + '</span>'
    + '</button></li>'
  ).join('');

  listEl.querySelectorAll('[data-goto-job]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const jobId = btn.getAttribute('data-goto-job');
      if(jobDetails[jobId]){
        if(typeof openJobDetail === 'function') openJobDetail(jobId);
        return;
      }
      /* لا تفاصيل مسجلة لهذا الإعلان (رابط تقديم مباشر) — نمرّر إليه فقط */
      const targetCard = document.querySelector('.card[data-job-id="' + jobId + '"]');
      if(targetCard){
        targetCard.scrollIntoView({behavior:'smooth', block:'center'});
        targetCard.style.transition = 'box-shadow .3s';
        targetCard.style.boxShadow = '0 0 0 3px var(--red)';
        setTimeout(()=>{ targetCard.style.boxShadow=''; }, 1400);
      }
    });
  });
}
renderUpdatesList();

/* ===== COUNTDOWN TO NEAREST DEADLINE ===== */
let countdownJobId = null;
let countdownTargetDate = null;
let countdownInterval = null;

function initCountdown(){
  const cards = Array.from(document.querySelectorAll('.card[data-countdown]'));
  const now = new Date();
  const future = cards.map(card=>({
    jobId: card.getAttribute('data-job-id'),
    target: new Date(card.getAttribute('data-countdown'))
  })).filter(it=> it.target > now)
    .sort((a,b)=> a.target - b.target);

  const grid = document.getElementById('countdownGrid');
  const labelEl = document.getElementById('countdownLabel');

  if(future.length === 0){
    if(grid) grid.style.display = 'none';
    if(labelEl) labelEl.textContent = dict.cdEmpty[currentLang];
    return;
  }

  countdownJobId = future[0].jobId;
  countdownTargetDate = future[0].target;
  renderCountdownLabel();
  if(grid) grid.style.display = '';

  if(countdownInterval) clearInterval(countdownInterval);
  tickCountdown();
  countdownInterval = setInterval(tickCountdown, 1000);
}

function renderCountdownLabel(){
  const labelEl = document.getElementById('countdownLabel');
  if(!labelEl || !countdownJobId) return;
  const titleDict = dict[countdownJobId + 'title'];
  const title = titleDict ? titleDict[currentLang] : '';
  labelEl.textContent = dict.cdLabelPrefix[currentLang] + title;
}

function tickCountdown(){
  if(!countdownTargetDate) return;
  const diff = countdownTargetDate - new Date();
  if(diff <= 0){
    clearInterval(countdownInterval);
    const grid = document.getElementById('countdownGrid');
    const labelEl = document.getElementById('countdownLabel');
    if(grid) grid.style.display = 'none';
    if(labelEl) labelEl.textContent = dict.cdExpired[currentLang];
    return;
  }
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  const seconds = Math.floor((diff % 60000) / 1000);
  const pad = n => String(n).padStart(2,'0');
  const cdDays = document.getElementById('cdDays');
  const cdHours = document.getElementById('cdHours');
  const cdMinutes = document.getElementById('cdMinutes');
  const cdSeconds = document.getElementById('cdSeconds');
  if(cdDays) cdDays.textContent = pad(days);
  if(cdHours) cdHours.textContent = pad(hours);
  if(cdMinutes) cdMinutes.textContent = pad(minutes);
  if(cdSeconds) cdSeconds.textContent = pad(seconds);
}
initCountdown();

/* ===== MODAL ACCESSIBILITY: focus trap + focus restore ===== */
let lastFocusedBeforeModal = null;
function lockModalFocus(modalEl){
  lastFocusedBeforeModal = document.activeElement;
  const focusable = modalEl.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])');
  if(focusable.length) focusable[0].focus();
}
function unlockModalFocus(){
  if(lastFocusedBeforeModal && typeof lastFocusedBeforeModal.focus === 'function'){
    lastFocusedBeforeModal.focus();
  }
  lastFocusedBeforeModal = null;
}
document.addEventListener('keydown', (e)=>{
  if(e.key !== 'Tab') return;
  const openModal = document.querySelector('.modal-overlay.open');
  if(!openModal) return;
  const focusable = Array.from(openModal.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'))
    .filter(el=> el.offsetParent !== null);
  if(focusable.length === 0) return;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if(e.shiftKey && document.activeElement === first){
    e.preventDefault();
    last.focus();
  }else if(!e.shiftKey && document.activeElement === last){
    e.preventDefault();
    first.focus();
  }
});

