const bacCalcModal = document.getElementById('bacCalcModal');
const bacCalcForm = document.getElementById('bacCalcForm');
const bcError = document.getElementById('bcError');
const bcResult = document.getElementById('bcResult');
const bcScoreValue = document.getElementById('bcScoreValue');
const bcMention = document.getElementById('bcMention');

document.querySelectorAll('[data-open-baccalc]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    bacCalcModal.classList.add('open');
    document.body.style.overflow = 'hidden';
    lockModalFocus(bacCalcModal);
  });
});
