function bacMentionKey(score){
  if(score < 10) return 'bcMentionFail';
  if(score < 12) return 'bcMentionPass';
  if(score < 14) return 'bcMentionAB';
  if(score < 16) return 'bcMentionBien';
  if(score < 18) return 'bcMentionTB';
  return 'bcMentionExc';
}
let lastBacMentionKey = null;

bacCalcForm.addEventListener('submit', (e)=>{
  e.preventDefault();
  const parseScore = (id)=>{
    const raw = document.getElementById(id).value.trim().replace(',', '.');
    return parseFloat(raw);
  };
  const cc = parseScore('bc_cc');
  const regional = parseScore('bc_regional');
  const national = parseScore('bc_national');
  const vals = [cc, regional, national];
  const valid = vals.every(v=> !isNaN(v) && v >= 0 && v <= 20);
  if(!valid){
    bcError.style.display = 'block';
    bcResult.classList.remove('show');
    return;
  }
  bcError.style.display = 'none';
  const score = (cc * 0.25) + (regional * 0.25) + (national * 0.5);
  bcScoreValue.textContent = score.toFixed(2);
  lastBacMentionKey = bacMentionKey(score);
  bcMention.textContent = dict[lastBacMentionKey][currentLang];
  const mentionColor = score < 10 ? 'var(--red)' : 'var(--green)';
  bcMention.style.color = mentionColor;
  bcResult.classList.add('show');
});

