const jobDetailModal = document.getElementById('jobDetailModal');
const jobDetailModalTitle = document.getElementById('jobDetailModalTitle');
const jobDetailModalTag = document.getElementById('jobDetailModalTag');
const directApplyLinks = {
  c7: 'https://www.habous.gov.ma/',
  c6: 'https://www.adm.co.ma/fr/offres-de-recrutement',
  p4: 'https://wa.me/212661910171',
  p6: 'mailto:tangermarocrecrutement@gmail.com',
  p7: 'mailto:tangermarocrecrutement@gmail.com',
  p8: 'mailto:rrecrutement08@gmail.com',
  p9: 'mailto:tangermarocrecrutement@gmail.com'
};
const jobDetailChips = document.getElementById('jobDetailChips');
const jobDetailBody = document.getElementById('jobDetailBody');
const jobDetailCta = document.getElementById('jobDetailCta');
const jobDetailNote = document.getElementById('jobDetailNote');
let currentJobDetailId = null;

function renderJobDetailContent(jobId){
  const info = jobDetails[jobId];
  if(!info) return;
  const langData = info[currentLang] || info.ar;

  jobDetailModalTitle.textContent = (dict[jobId + 'title'] && dict[jobId + 'title'][currentLang]) || '';
  jobDetailModalTag.textContent = (dict[jobId + 'tag'] && dict[jobId + 'tag'][currentLang]) || '';

  let chipsHtml = '';
  if(dict[jobId + 'meta']) chipsHtml += '<span class="meta">' + dict[jobId + 'meta'][currentLang] + '</span>';
  if(dict[jobId + 'deadline']) chipsHtml += '<span class="deadline">' + dict[jobId + 'deadline'][currentLang] + '</span>';
  jobDetailChips.innerHTML = chipsHtml;

  let bodyHtml = '';
  if(dict[jobId + 'desc']) bodyHtml += '<p class="legal-intro">' + dict[jobId + 'desc'][currentLang] + '</p>';
  (langData.sections || []).forEach(sec=>{
    let inner = '<h2>' + sec.h + '</h2>';
    if(sec.p) inner += '<p>' + sec.p + '</p>';
    if(sec.list) inner += '<ul>' + sec.list.map(li=> '<li>' + li + '</li>').join('') + '</ul>';
    bodyHtml += '<div class="legal-section">' + inner + '</div>';
  });
  jobDetailBody.innerHTML = bodyHtml;

  const isArticle = jobId.charAt(0) === 'a';
  if(isArticle){
    jobDetailCta.style.display = 'none';
    const articleCard = document.querySelector('.card[data-job-id="' + jobId + '"]');
    const articleType = articleCard ? articleCard.getAttribute('data-article-type') : null;
    /* opinion → avertissement de l'auteur ; tutorial → note indicative */
    const noteDict = (articleType === 'tutorial') ? dict.tutorialNote : dict.articleNote;
    jobDetailNote.textContent = noteDict[currentLang];
  }else{
    jobDetailCta.style.display = '';
    if(directApplyLinks[jobId]){
      jobDetailCta.href = directApplyLinks[jobId];
      if(directApplyLinks[jobId].startsWith('http')){
        jobDetailCta.setAttribute('target', '_blank');
        jobDetailCta.setAttribute('rel', 'noopener');
      }else{
        jobDetailCta.removeAttribute('target');
        jobDetailCta.removeAttribute('rel');
      }
      jobDetailCta.textContent = (dict[jobId + 'apply'] && dict[jobId + 'apply'][currentLang]) || dict.jdApplyBtn[currentLang];
    }else{
      jobDetailCta.href = '#';
      jobDetailCta.removeAttribute('target');
      jobDetailCta.removeAttribute('rel');
      jobDetailCta.textContent = dict.jdApplyBtn[currentLang];
    }
    jobDetailNote.textContent = dict.jdSourceNote[currentLang];
  }
}

function openJobDetail(jobId){
  if(!jobDetails[jobId]) return;
  currentJobDetailId = jobId;
  renderJobDetailContent(jobId);
  jobDetailModal.classList.add('open');
  document.body.style.overflow = 'hidden';
  jobDetailModal.scrollTop = 0;
  const box = jobDetailModal.querySelector('.modal-box');
  if(box) box.scrollTop = 0;
  lockModalFocus(jobDetailModal);
}
function closeJobDetailModal(){
  if(!jobDetailModal.classList.contains('open')) return;
  jobDetailModal.classList.remove('open');
  document.body.style.overflow = '';
  currentJobDetailId = null;
  unlockModalFocus();
}

