/* ===== SAVE / BOOKMARK ===== */
function getSaved(){
  try{ return JSON.parse(localStorage.getItem('jm_saved') || '[]'); }catch(e){ return []; }
}
function setSaved(arr){
  try{ localStorage.setItem('jm_saved', JSON.stringify(arr)); }catch(e){}
}
const savedCountEl = document.getElementById('savedCount');

function refreshSaveUI(){
  const saved = getSaved();
  document.querySelectorAll('[data-save-btn]').forEach(btn=>{
    const id = btn.getAttribute('data-job-id');
    btn.classList.toggle('saved', saved.includes(id));
  });
  if(saved.length > 0){
    savedCountEl.style.display = 'flex';
    savedCountEl.textContent = saved.length;
  }else{
    savedCountEl.style.display = 'none';
  }
}
document.querySelectorAll('[data-save-btn]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    const id = btn.getAttribute('data-job-id');
    let saved = getSaved();
    if(saved.includes(id)){ saved = saved.filter(x=> x!==id); }
    else{ saved.push(id); }
    setSaved(saved);
    refreshSaveUI();
    renderSavedList();
  });
});
refreshSaveUI();

function renderSavedList(){
  const saved = getSaved();
  const savedList = document.getElementById('savedList');
  const savedEmpty = document.getElementById('savedEmpty');
  savedList.innerHTML = '';
  if(saved.length === 0){
    savedEmpty.style.display = 'block';
    return;
  }
  savedEmpty.style.display = 'none';
  saved.forEach(id=>{
    const card = document.querySelector(`.card[data-job-id="${id}"]`);
    if(!card) return;
    const title = card.querySelector('h3') ? card.querySelector('h3').textContent : id;
    const li = document.createElement('li');
    li.style.display = 'flex';
    li.style.justifyContent = 'space-between';
    li.style.alignItems = 'center';
    li.style.gap = '10px';
    const span = document.createElement('span');
    span.textContent = title;
    span.style.cursor = 'pointer';
    span.addEventListener('click', ()=>{
      closeSavedModal();
      card.scrollIntoView({behavior:'smooth', block:'center'});
      card.style.transition = 'box-shadow .3s';
      card.style.boxShadow = '0 0 0 3px var(--red)';
      setTimeout(()=>{ card.style.boxShadow=''; }, 1400);
    });
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.textContent = dict.savedRemove[currentLang];
    removeBtn.style.cssText = 'font-size:11.5px;color:var(--red);background:none;border:1px solid var(--red);border-radius:7px;padding:4px 8px;flex-shrink:0;';
    removeBtn.addEventListener('click', ()=>{
      let s = getSaved().filter(x=> x!==id);
      setSaved(s);
      refreshSaveUI();
      renderSavedList();
    });
    li.appendChild(span);
    li.appendChild(removeBtn);
    savedList.appendChild(li);
  });
}
renderSavedList();

const savedModal = document.getElementById('savedModal');
const savedToggle = document.getElementById('savedToggle');
savedToggle.addEventListener('click', ()=>{
  renderSavedList();
  savedModal.classList.add('open');
  document.body.style.overflow = 'hidden';
  lockModalFocus(savedModal);
});
function closeSavedModal(){
  if(!savedModal.classList.contains('open')) return;
  savedModal.classList.remove('open');
  document.body.style.overflow = '';
  unlockModalFocus();
}
document.querySelectorAll('[data-close-saved]').forEach(btn=> btn.addEventListener('click', closeSavedModal));

const emailModal = document.getElementById('emailModal');
const footerEmailBtn = document.getElementById('footerEmailBtn');
const emailCopyBtn = document.getElementById('emailCopyBtn');
const emailCopyNote = document.getElementById('emailCopyNote');
const EMAIL_ADDR = 'forsajobs.contact@gmail.com';

function openEmailModal(e){
  e.preventDefault();
  emailModal.classList.add('open');
  document.body.style.overflow = 'hidden';
  lockModalFocus(emailModal);
}
function closeEmailModal(){
  if(!emailModal.classList.contains('open')) return;
  emailModal.classList.remove('open');
  document.body.style.overflow = '';
  unlockModalFocus();
}
if(footerEmailBtn) footerEmailBtn.addEventListener('click', openEmailModal);
document.querySelectorAll('[data-close-email]').forEach(btn=> btn.addEventListener('click', closeEmailModal));
emailModal.addEventListener('click', (e)=>{ if(e.target === emailModal) closeEmailModal(); });
if(emailCopyBtn){
  emailCopyBtn.addEventListener('click', async ()=>{
    try{
      await navigator.clipboard.writeText(EMAIL_ADDR);
      emailCopyNote.textContent = dict.emailModalCopied[currentLang];
      emailCopyNote.classList.add('show');
      setTimeout(()=> emailCopyNote.classList.remove('show'), 2600);
    }catch(e){ /* clipboard unavailable — the address is still shown as text */ }
  });
}

savedModal.addEventListener('click', (e)=>{ if(e.target === savedModal) closeSavedModal(); });

