/* فتح تلقائي لإعلان معيّن إذا كان الرابط يحتوي على #job=ID (روابط المشاركة) */
(function openFromShareLink(){
  const m = location.hash.match(/^#job=(.+)$/);
  if(m && jobDetails[m[1]]){
    setTimeout(()=> openJobDetail(m[1]), 50);
  }
})();
